-- Preserve old Market package screen access before introducing independent screen grants.
UPDATE pos_entitlements e SET allowed = (
 SELECT COALESCE(jsonb_agg(DISTINCT key), '[]'::jsonb) FROM (
  SELECT jsonb_array_elements_text(e.allowed) AS key
  UNION ALL SELECT section->>'key' FROM jsonb_array_elements('[{"key": "OPS_GOODS", "label": "Mallar", "legacy": ["CREATE_PRODUCT", "EDIT_PRODUCT", "EDIT_PRICE", "EDIT_STOCK"]}, {"key": "OPS_STOCK", "label": "Anbar", "legacy": ["EDIT_STOCK", "STOCK_ADJUSTMENT", "VIEW_COST"]}, {"key": "OPS_TRANSFERS", "label": "Yerdəyişmələr", "legacy": ["TRANSFER_STOCK"]}, {"key": "OPS_PURCHASES", "label": "Alışlar", "legacy": ["RECEIVE_PURCHASE", "DOCS_VIEW", "DOCS_CREATE", "DOCS_EDIT", "DOCS_DELETE"]}, {"key": "OPS_STOCKTAKE", "label": "Sayım", "legacy": ["STOCK_ADJUSTMENT"]}, {"key": "OPS_CATEGORIES", "label": "Kateqoriyalar", "legacy": ["CREATE_PRODUCT", "EDIT_PRODUCT", "EDIT_PRICE", "EDIT_STOCK"]}, {"key": "OPS_PARTNERS", "label": "Partnyorlar", "legacy": ["RECEIVE_PURCHASE", "DOCS_VIEW", "DOCS_CREATE", "DOCS_EDIT", "DOCS_DELETE"]}, {"key": "OPS_SALES", "label": "Satışlar", "legacy": ["VIEW_REPORTS"]}, {"key": "OPS_CASH", "label": "Kassalar", "legacy": ["CASH_IN", "CASH_OUT", "SAFE_DROP", "CLOSE_SHIFT"]}, {"key": "OPS_EXPENSES", "label": "Xərclər", "legacy": ["CASH_IN", "CASH_OUT", "SAFE_DROP", "CLOSE_SHIFT"]}, {"key": "OPS_SALARY", "label": "Maaşlar", "legacy": ["MANAGE_USERS"]}, {"key": "OPS_DOCUMENTS", "label": "Ödəniş qaimələri", "legacy": ["DOCS_VIEW", "DOCS_CREATE", "DOCS_EDIT", "DOCS_DELETE"]}, {"key": "OPS_PROFIT", "label": "Qazanc", "legacy": ["VIEW_PROFIT"]}, {"key": "OPS_EXPORT", "label": "İxrac", "legacy": ["VIEW_REPORTS"]}, {"key": "OPS_USERS", "label": "İstifadəçilər", "legacy": ["MANAGE_USERS"]}]'::jsonb) section
  WHERE EXISTS (SELECT 1 FROM jsonb_array_elements_text(section->'legacy') legacy WHERE e.allowed ? legacy)
 ) keys
), updated_at=now() WHERE product='market';
UPDATE pos_role_policy SET version=version+1,updated_at=now() WHERE product='market';
